      '\nCREATE UNIQUE INDEX IF NOT EXISTS "activity_message_record_idx" ON "activity" USING btree ("message_id", coalesce("contact_id", \'\'), coalesce("lead_id", \'\')) WHERE "message_id" IS NOT NULL;\n',
